describe('Promo Code Expiration Error Handling', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when user enters expired promo code', () => {
    // Intercept the API call to validate promo code
    cy.intercept('POST', '/api/validate-promo-code', {
      statusCode: 200,
      body: {
        success: false,
        message: 'Promo code has expired',
        expirationDate: '2023-01-01T00:00:00Z'
      }
    }).as('validatePromoCode');

    // Get the promo code input field
    cy.get('[data-testid="promo-code-input"]').type('EXPIRED123');

    // Submit the form
    cy.get('[data-testid="apply-promo-button"]').click();

    // Wait for the API response
    cy.wait('@validatePromoCode');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Promo code has expired');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]')
      .should('not.exist');

    // Verify promo code input field is cleared
    cy.get('[data-testid="promo-code-input"]').should('have.value', '');
  });

  it('should handle edge case when promo code is valid but expired', () => {
    // Intercept the API call with a valid but expired promo code
    cy.intercept('POST', '/api/validate-promo-code', {
      statusCode: 200,
      body: {
        success: true,
        message: 'Promo code has expired',
        expirationDate: '2023-01-01T00:00:00Z'
      }
    }).as('validatePromoCodeExpired');

    // Get the promo code input field
    cy.get('[data-testid="promo-code-input"]').type('VALIDCODE2023');

    // Submit the form
    cy.get('[data-testid="apply-promo-button"]').click();

    // Wait for the API response
    cy.wait('@validatePromoCodeExpired');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Promo code has expired');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]')
      .should('not.exist');

    // Verify promo code input field is cleared
    cy.get('[data-testid="promo-code-input"]').should('have.value', '');
  });
});
